window.WORLD_TWO_ENDING=[{who:'ผู้เล่า',face:'🌙',text:'สายน้ำจากโอเอซิสพุ่งขึ้นสู่ฟ้า ผลึกหัวใจชิ้นที่สองลอยลงสู่มือของนักผจญภัย และทะเลทรายกลับมามีชีวิตอีกครั้ง'},{who:'วิญญาณโอเอซิส',face:'💧',text:'ผู้ใช้พลังตัวเลขเอ๋ย เจ้าคืนสายน้ำให้บ้านของเรา รับแสงชิ้นนี้ไว้ตามหาหัวใจแห่งป่าต่อไปเถิด'},{who:'ชิป',face:'🐿️',text:'สองชิ้นแล้ว! เหลืออีกแปดชิ้น… และถั่วฉลองอย่างน้อยแปดถุง นี่เป็นคณิตศาสตร์ที่สำคัญมากนะ'},{who:'ฟลัฟฟี่',face:'🐇',text:'ดูนั่นสิ ประตูเห็ดยักษ์เปิดแล้ว แต่เงาข้างในตัวใหญ่กว่าประตูอีก!'},{who:'พ่อมดเงา',face:'🧙🏿‍♂️',text:'เก่งกว่าที่ข้าคิด แต่ผู้พิทักษ์อาณาจักรเห็ดจะทำให้พวกเจ้าลืมแม้กระทั่งชื่อตัวเอง!'},{who:'แบมแบม',face:'🧒🏻',text:'เราเรียนรู้ทั้งการรวม แยก คูณ และจัดกลุ่มพลังแล้ว ต่อให้โลกถัดไปมีอะไร ทีมของเราก็พร้อมไปด้วยกัน!'}];
